    const int table = index / batch;
    const int kind = table & 1;
    const int panel = table >> 1;
    const int start = panel * block;
    const int stop = min(start + block, n);
    const int64_t matrix_base = static_cast<int64_t>(matrix) * n * n;
    const int64_t element = kind == 0
        ? matrix_base + static_cast<int64_t>(start) * (n + 1)
        : matrix_base + static_cast<int64_t>(start) * n + stop;
    pointers[index] = reinterpret_cast<int64_t>(output + element);

        else (128 * warp_n if elem_width_d == 6 else 128 // elem_width_d * warp_n)
    )
    n_min_c = (
        8 * warp_n
        if (c_is_m_major or disable_source)
        else (128 * warp_n if elem_width_c == 6 else 128 // elem_width_c * warp_n)  # type: ignore[operator]
    )

    # -- Step 5: tile_n ---------------------------------------------------
    tile_n = min(cta_tile_n, max(n_perf, n_min_c, n_min_d))
    # If the final tile_n doesn't divide cta_tile_n, fall back to full N.
    if cta_tile_n % tile_n != 0:
        tile_n = cta_tile_n

    return (tile_m, tile_n)


